mapper.update:
UPDATE t_task
task_biz_id = #{taskBizId}, task_name = #{taskName}, executor_type = #{executorType}, wait_strategy = #{waitStrategy, typeHandler=org.apache.ibatis.type.EnumTypeHandler}, status = #{status}, sub_status = #{subStatus}, failure_reason = #{failureReason}, session_id = #{sessionId}, input_data = #{inputData}, output_data = #{outputData}, wakeup_context = #{wakeupContext}, scheduled_time = #{scheduledTime}, start_time = #{startTime}, end_time = #{endTime}, expire_time = #{expireTime}, retry_count = #{retryCount}, error_msg = #{errorMsg}, update_time = #{updateTime},
WHERE id = #{id}

mapper.select:
SELECT * FROM t_task
WHERE task_biz_id = #{taskBizId}
AND task_type_code = #{taskTypeCode}

SELECT * FROM t_task
WHERE status = 'PENDING'
  AND (
        (scheduled_time IS NULL AND create_time <= #{scheduledBefore})
        OR scheduled_time <= #{scheduledBefore}
      )
ORDER BY priority DESC, create_time ASC
LIMIT #{limit}

SELECT * FROM t_task
WHERE status = 'RUNNING'
  AND start_time IS NOT NULL
  AND start_time < #{threshold}
ORDER BY start_time ASC
LIMIT #{limit}

SELECT * FROM t_task
WHERE status = #{status}
ORDER BY priority DESC, create_time ASC
LIMIT #{offset}, #{limit}
